# 40 Meta paid-ad scripts (A01–A40), built from ADS.md concepts for the BLITZ charge-today founding offer.
# Rendered + validated by tools/build_content.py -> ADS_SCRIPTS.md and data/content/ad_scripts.json.
# body beat tuple: (time, VO or action, on-screen text). Hooks cover 0–2 s; body starts at 2 s.
# offer: "founding" (charge-today founding membership, MRR) or "gift" (prepaid, charged today, not MRR; feeds recipient conversion).
# CANON UPDATE 2/3: there is no $1 trial. Every ad ships a STARTER variant (the launch default, cell B): swap the offer line
# for STARTER_LINE, the end card for END_STARTER and the URL for /b?t=BOOK. Paid ads run only after the BLITZ.md §11 gate.

FOUNDING_LINE = ("Founding Membership: {{FOUNDING_PRICE}}/month, first month charged today, renews monthly at the same price until you cancel. "
                 "Cancel online anytime. 14-day money-back guarantee on the membership charge, one per person. "
                 "Your founding price stays locked while you stay subscribed, pauses included. "
                 "Founding price open to everyone until {{FOUNDING_CLOSE_DATE}}.")
STARTER_LINE = ("Start for $12 today: both Starter Books (yours to keep) and your first month as a founding member, then $25/month. "
                "Renews monthly until you cancel. Cancel online anytime. 14-day money-back guarantee on the membership charge, one per person.")
GIFT_LINE = ("Give 3 months for $49 or 12 months for $119, prepaid and charged today. "
             "It starts the day they open it and never auto-renews.")
GIFT_STARTER_LINE = "Or they can start for $12 today: both Starter Books and the first month, then $25/month as a founding member. Renews monthly until cancelled. Cancel online anytime."
END_FOUNDING = "Session screen + 'Founding Membership · {{FOUNDING_PRICE}}/mo · charged today · renews monthly · cancel online anytime · 14-day money-back guarantee' (full contrast, Ink on Paper)"
END_STARTER = "Session screen + '$12 today: both books + your first month · then $25/mo · renews monthly · cancel online anytime'"
END_GIFT = "Gift card graphic + '3 months $49 · 12 months $119 · prepaid · never auto-renews'"
DISC = "Built on published exercise guidelines for older adults. Check with your doctor before starting new exercise."
DISC_K = "Recipes built on published nutrition guidance for older adults. Not medical advice."

OPT_F = "Subscribe (server-side at checkout, value = month-one price; dedup with Purchase). Fallback if the pixel is health-restricted: Purchase, then Lead with a cost cap."
OPT_Q = "Subscribe from the quiz result page (Founding Membership offer; starter variant: Purchase + Subscribe at the $12 checkout). Fallback: Purchase; if restricted, Lead (q_a_complete) with a cost cap, judged on back-end MRR per $."
OPT_G = "Purchase (gift checkout, value = gift price). Fallback: Lead with a cost cap."

